<script module lang="ts">
/**
 * Plays one recording (`design/components/audio-player.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/audio-player.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  Icon,
  agentMember,
  clockTime,
  joinSlot,
  pauseOtherPlayers,
  spokenDuration,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/audio-player.module.css'
import Button from '../controls/Button.svelte'
import Slider from '../controls/Slider.svelte'

export interface AudioPlayerMessages {
  /** The Button's name while the recording is not playing: "Play". */
  play: string
  /** The Button's name while it plays: "Pause". */
  pause: string
  /** The scrubber's name: "Playback position". */
  scrubber: string
  /** The scrubber's spoken value, from the elapsed and the total length. */
  position: (elapsed: string, total: string) => string
  /** Said in place of the scrubber when the file cannot be loaded. */
  failed: string
}

export interface AudioPlayerProps {
  /**
   * The recording's length in seconds, shown before the file gives its own. A file's finite
   * length replaces it. A file that gives none, as a recording a browser's `MediaRecorder`
   * wrote, keeps it.
   */
  duration?: number
  /**
   * Names the player, as a group: "Voice message from Ada".
   */
  label: string
  /**
   * The locale the clock and the spoken lengths are written in; the page's own when absent.
   */
  locale?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: AudioPlayerMessages
  /**
   * The recording played to its end.
   */
  onEnded?: () => void
  /**
   * The recording started playing, from a press on its Button.
   */
  onPlay?: () => void
  /**
   * The recording's URL. An empty string is the failed state: there is nothing to load.
   */
  src: string
}
</script>

<script lang="ts">
let {
  duration,
  label: labelOwn,
  locale,
  messages = (() => ({
    play: 'Play',
    pause: 'Pause',
    scrubber: 'Playback position',
    position: (elapsed: string, total: string) => `${elapsed} of ${total}`,
    failed: 'The recording could not be loaded',
  }))(),
  onEnded,
  onPlay,
  src,
}: AudioPlayerProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let playing = $state(false)
let finished = $state(false)
let elapsed = $state(0)
let fileLength = $state(null as number | null)
let failed = $state(null as string | null)
let scrub = $state(null as number | null)
let audio = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
const known = $derived(
  fileLength ??
    (duration !== undefined && Number.isFinite(duration) && duration > 0 ? duration : null),
)
const total = $derived(known === null ? 0 : Math.floor(known))
const failing = $derived(src === '' || failed === src)
const seekable = $derived(!failing && total >= 1)
const position = $derived(finished ? total : Math.min(scrub ?? elapsed, total))
const status = $derived(failing ? 'failed' : playing ? 'playing' : finished ? 'ended' : undefined)
const failureId = $derived(`${uid}-failure`)
const spoken = $derived((second: number): string =>
  known === null
    ? spokenDuration(second, locale)
    : messages.position(spokenDuration(second, locale), spokenDuration(total, locale)),
)
const learn = $derived((): void => {
  const element = audio as HTMLAudioElement | null | undefined
  if (element == null) return
  const seconds = element.duration
  fileLength = Number.isFinite(seconds) && seconds > 0 ? seconds : null
})
const settle = $derived((): void => {
  playing = false
  finished = false
  elapsed = 0
  fileLength = null
  scrub = null
  if (failed !== src) failed = null
  const element = audio as HTMLAudioElement | null | undefined
  if (element == null) return
  if (element.error !== null) failed = src
  else if (element.readyState >= 1) learn()
})
const toggle = $derived((): void => {
  const element = audio as HTMLAudioElement | null | undefined
  if (element == null) return
  if (!element.paused) {
    element.pause()
    return
  }
  if (failing) {
    failed = null
    element.load()
  }
  element.play().catch(() => {})
})
const secondOf = $derived((value: number | [number, number]): number =>
  typeof value === 'number' ? value : value[0],
)
const seek = $derived((second: number): void => {
  scrub = null
  elapsed = second
  finished = false
  const element = audio as HTMLAudioElement | null | undefined
  if (element != null) element.currentTime = second
})
const started = $derived((): void => {
  playing = true
  finished = false
  const element = audio as HTMLAudioElement | null | undefined
  if (element != null) pauseOtherPlayers(element)
  onPlay?.()
})
const stopped = $derived((): void => {
  playing = false
  finished = true
  onEnded?.()
})
const ticked = $derived((): void => {
  const element = audio as HTMLAudioElement | null | undefined
  if (element != null) elapsed = Math.floor(element.currentTime)
})
const effect1 = () => {
  settle()
}
watchEffect(effect1, { watch: () => src })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'AudioPlayer',
    element: () => root,
    state: () => ({ playing: playing, failed: failing, position: position, duration: total }),
    actions: {},
    withholds: () => root,
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.root}
    role="group"
    aria-label={label}
    data-state={status}
    data-member="audio-player"
    >{#if src !== ''
      }<audio
        bind:this={audio}
        preload="metadata"
        {src}
        onloadedmetadata={() => { learn() }}
        ondurationchange={() => { learn() }}
        ontimeupdate={() => { ticked() }}
        onplay={() => { started() }}
        onpause={() => { playing = false }}
        onended={() => { stopped() }}
        onerror={() => { (failed = src, playing = false) }}
      ></audio
    >{/if
    }<Button
      variant="soft"
      tone="accent"
      iconOnly={true}
      icon={playing ? 'pause' : 'run'}
      label={playing ? messages.pause : messages.play}
      disabled={src === ''}
      aria-describedby={failing ? failureId : undefined}
      onClick={() => { toggle() }}
    />{#if failing
      }<span class={styles.failure} id={failureId} data-audio-player-part="failure"
        ><span class={styles.failureGlyph} aria-hidden="true"><Icon name="error" size="sm" /></span
        ><span>{messages.failed}</span
      ></span
    >{:else
      }<span class={styles.scrubber}
        ><Slider
          aria-label={messages.scrubber}
          min={0}
          max={seekable ? total : 1}
          step={1}
          value={seekable ? position : 0}
          disabled={!seekable}
          formatValue={spoken}
          onChange={(value: number | [number, number]) => { scrub = secondOf(value) }}
          onCommit={(value: number | [number, number]) => seek(scrub ?? secondOf(value))}
      /></span
      ><span class={styles.time} data-audio-player-part="time" aria-hidden="true"
        ><span>{clockTime(position, locale)}</span
        >{#if known !== null
          }<span class={styles.divider}>{'/'}</span
          ><span>{clockTime(total, locale)}</span
        >{/if
      }</span
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
